sp_widget.client_script:
api.controller = function($window, $sce) {

    var c = this;


    /* =====================================================
       INITIAL STATE
       ===================================================== */

    c.sidebarOpen = $window.innerWidth > 900;

    c.loading = false;

    c.refreshing = false;

    c.actionLoading = false;

    c.selectedInterview = null;

    c.qrInterview = null;

    c.performanceInterview = null;

    c.qrFrameUrl = '';

    c.lastUpdated = '';


    /* =====================================================
       SIDEBAR
       ===================================================== */

    c.toggleSidebar = function() {

        c.sidebarOpen = !c.sidebarOpen;

    };


    c.closeSidebar = function() {

        c.sidebarOpen = false;

    };


    /* =====================================================
       NAVIGATION
       ===================================================== */

    c.navigate = function(pageId) {

        if (!pageId) {
            return;
        }

        c.sidebarOpen = false;

        var studentId = '';

        if (
            c.data &&
            c.data.studentId
        ) {

            studentId = c.data.studentId;

        }

        /*
         * The Server Script reads:
         *
         * $sp.getParameter('student')
         *
         * so preserve the student parameter when navigating.
         */

        var url =
            '?id=' +
            encodeURIComponent(pageId);

        if (studentId) {

            url +=
                '&student=' +
                encodeURIComponent(studentId);

        }

        $window.location.href = url;

    };


    /* =====================================================
       STUDENT DISPLAY
       ===================================================== */

    c.getStudentName = function() {

        /*
         * Your current Server Script does not return
         * data.student or data.studentId.
         *
         * Therefore use the URL student parameter when
         * available.
         */

        var student =
            new URLSearchParams(
                $window.location.search
            ).get('student');

        return student || 'Student';

    };


    c.getStudentInitials = function() {

        var name =
            c.getStudentName();

        if (!name) {
            return 'S';
        }

        var parts =
            name.trim().split(/\s+/);

        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }

        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    };


    /* =====================================================
       REFRESH
       ===================================================== */

    c.refresh = function() {

        c.refreshing = true;

        /*
         * This does NOT modify interview records.
         *
         * It simply executes the supplied Server Script
         * again and reloads the read-only data.
         */

        c.server.update().then(
            function(response) {

                c.refreshing = false;

                c.lastUpdated =
                    new Date()
                    .toLocaleTimeString();

            },
            function() {

                c.refreshing = false;

            }
        );

    };


    /* =====================================================
       START INTERVIEW
       ===================================================== */

    c.startInterview = function(interview) {

        if (!interview) {
            return;
        }

        /*
         * IMPORTANT:
         *
         * Do NOT update interview_status here.
         *
         * Do NOT call:
         *
         * c.server.update()
         *
         * Do NOT send:
         *
         * start_interview
         *
         * to the Server Script.
         *
         * The supplied Server Script is read-only.
         *
         * We simply open the QR URL already stored
         * in the interview record.
         */

        c.openQR(interview);

    };


    /* =====================================================
       OPEN QR
       ===================================================== */

    c.openQR = function(interview) {

        if (!interview) {
            return;
        }

        c.qrInterview = interview;

        c.qrFrameUrl = '';

        /*
         * qr_url is supplied directly by your Server Script:
         *
         * qr_url:
         *     interviewGR.getValue('qr_url')
         */

        if (
            interview.qr_url &&
            String(interview.qr_url).trim()
        ) {

            c.qrFrameUrl =
                $sce.trustAsResourceUrl(
                    String(interview.qr_url)
                );

        }

    };


    /* =====================================================
       CLOSE QR
       ===================================================== */

    c.closeQR = function() {

        c.qrInterview = null;

        c.qrFrameUrl = '';

    };


    /* =====================================================
       REFRESH AFTER QR
       ===================================================== */

    c.refreshAfterQR = function() {

        c.refresh();

    };


    /* =====================================================
       INTERVIEW DETAILS
       ===================================================== */

    c.viewInterview = function(interview) {

        c.selectedInterview =
            interview;

    };


    c.closeInterview = function() {

        c.selectedInterview =
            null;

    };


    /* =====================================================
       PERFORMANCE
       ===================================================== */

    c.viewPerformance = function(interview) {

        c.performanceInterview =
            interview;

    };


    c.closePerformance = function() {

        c.performanceInterview =
            null;

    };


    /* =====================================================
       STATUS CLASS
       ===================================================== */

    c.getStatusClass = function(status) {

        if (status === 'Scheduled') {

            return 'status-scheduled';

        }

        if (status === 'In Progress') {

            return 'status-progress';

        }

        if (status === 'Completed') {

            return 'status-completed';

        }

        return 'status-default';

    };


    /* =====================================================
       STATUS LINE CLASS
       ===================================================== */

    c.getStatusLineClass = function(status) {

        if (status === 'Scheduled') {

            return 'status-line-scheduled';

        }

        if (status === 'In Progress') {

            return 'status-line-progress';

        }

        if (status === 'Completed') {

            return 'status-line-completed';

        }

        return 'status-line-default';

    };


    /* =====================================================
       ICON CLASS
       ===================================================== */

    c.getIconClass = function(status) {

        if (status === 'Scheduled') {

            return 'icon-scheduled';

        }

        if (status === 'In Progress') {

            return 'icon-progress';

        }

        if (status === 'Completed') {

            return 'icon-completed';

        }

        return '';

    };


    /* =====================================================
       ATTENDANCE CLASS
       ===================================================== */

    c.getAttendanceClass = function(status) {

        if (status === 'Present') {

            return 'attendance-present';

        }

        if (status === 'Scheduled') {

            return 'attendance-scheduled';

        }

        return 'attendance-default';

    };


    /* =====================================================
       WINDOW RESIZE
       ===================================================== */

    angular.element($window).on(
        'resize',
        function() {

            /*
             * Keep the hamburger visible at all times.
             *
             * Only automatically close the sidebar when
             * moving into the mobile layout.
             */

            if ($window.innerWidth <= 900) {

                c.sidebarOpen = false;

            }

        }
    );


    /* =====================================================
       CLEANUP
       ===================================================== */

    c.$onDestroy = function() {

        try {

            angular.element($window).off(
                'resize'
            );

        } catch (e) {}

    };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 STUDENT INTERVIEWS
   SAME NAVIGATION SYSTEM AS APPLICATIONS / OPPORTUNITIES
   FULL 100% VIEW
   ========================================================= */


/* =========================================================
   SERVICE NOW OUTER RESET
   ========================================================= */

html,
body {

  margin: 0 !important;
  padding: 0 !important;

  width: 100% !important;
  max-width: none !important;

}


body:has(.campus360-interviews) {

  margin: 0 !important;
  padding: 0 !important;

  overflow: hidden !important;

  background: #f3f6fb !important;

}


/* Remove common ServiceNow portal chrome.
   Campus360's own header is NOT targeted. */

body:has(.campus360-interviews) #sp-nav,
body:has(.campus360-interviews) .sp-navbar,
body:has(.campus360-interviews) .sp-header,
body:has(.campus360-interviews) .sp-header-bar,
body:has(.campus360-interviews) .portal-header,
body:has(.campus360-interviews) nav.navbar,
body:has(.campus360-interviews) .navbar.navbar-default {

  display: none !important;

}


/* Bootstrap / ServiceNow wrappers */

body:has(.campus360-interviews) .container,
body:has(.campus360-interviews) .container-fluid,
body:has(.campus360-interviews) .row,
body:has(.campus360-interviews) [class*="col-"],
body:has(.campus360-interviews) .well,
body:has(.campus360-interviews) .panel {

  width: 100% !important;

  max-width: none !important;

  min-width: 0 !important;

  margin: 0 !important;

  padding-left: 0 !important;

  padding-right: 0 !important;

}


body:has(.campus360-interviews) .panel-body {

  width: 100% !important;

  max-width: none !important;

  margin: 0 !important;

  padding: 0 !important;

}


/* =========================================================
   ROOT
   ========================================================= */

.campus360-interviews {

  position: fixed !important;

  inset: 0 !important;

  width: 100vw !important;

  height: 100vh !important;

  min-width: 100vw !important;

  min-height: 100vh !important;

  max-width: 100vw !important;

  max-height: 100vh !important;

  margin: 0 !important;

  padding: 0 !important;

  overflow: hidden !important;

  background:
    linear-gradient(
      135deg,
      #f1f6fc 0%,
      #f7f4ff 50%,
      #f0f8f6 100%
    );

  color: #10243f;

  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Arial,
    sans-serif;

  z-index: 999999 !important;

}


.campus360-interviews *,
.campus360-interviews *::before,
.campus360-interviews *::after {

  box-sizing: border-box;

}


/* =========================================================
   SIDEBAR
   ========================================================= */

.c360-left-sidebar {

  position: absolute !important;

  left: 0;

  top: 0;

  bottom: 0;

  width: 285px !important;

  min-width: 285px !important;

  max-width: 285px !important;

  height: 100vh !important;

  z-index: 100;

  display: flex;

  flex-direction: column;

  overflow: hidden;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right:
    1px solid #2d2157 !important;

  box-shadow:
    4px 0 18px
    rgba(0,0,0,.14);

  transition:
    transform .25s ease;

}


.campus360-interviews.sidebar-closed
.c360-left-sidebar {

  transform:
    translateX(-105%);

}


/* =========================================================
   BRAND
   ========================================================= */

.c360-sidebar-brand {

  height: 88px;

  min-height: 88px;

  flex: 0 0 88px;

  padding:
    0 20px;

  display: flex;

  align-items: center;

  gap: 12px;

  border-bottom:
    1px solid rgba(255,255,255,.08);

}


.c360-brand-logo {

  width: 48px;

  height: 48px;

  min-width: 48px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #9333ea
    );

  color: #ffffff;

  font-size: 23px;

  font-weight: 900;

  box-shadow:
    0 7px 18px
    rgba(124,58,237,.34);

}


.c360-brand-name {

  min-width: 0;

}


.c360-brand-name strong {

  display: block;

  color: #ffffff;

  font-size: 20px;

  line-height: 1;

  font-weight: 900;

}


.c360-brand-name span {

  display: block;

  margin-top: 5px;

  color: #c4b5fd;

  font-size: 11px;

  font-weight: 800;

}


/* =========================================================
   STUDENT PROFILE CARD
   ========================================================= */

.c360-sidebar-student {

  margin:
    18px
    13px
    10px;

  min-height: 67px;

  padding: 12px;

  display: flex;

  align-items: center;

  gap: 10px;

  border:
    1px solid #3c2b69;

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      #1f1448,
      #21154d
    );

  color: #ffffff !important;

  text-decoration: none !important;

  transition: .2s ease;

}


.c360-sidebar-student:hover {

  border-color: #5b3ea2;

  background:
    linear-gradient(
      145deg,
      #271957,
      #2b1c61
    );

  box-shadow:
    0 8px 20px
    rgba(124,58,237,.18);

}


.c360-sidebar-avatar {

  width: 43px;

  height: 43px;

  min-width: 43px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background:
    linear-gradient(
      135deg,
      #8b5cf6,
      #7c3aed
    );

  color: #ffffff;

  font-size: 11px;

  font-weight: 900;

  box-shadow:
    0 6px 16px
    rgba(124,58,237,.28);

}


.c360-sidebar-student-info {

  min-width: 0;

  flex: 1;

}


.c360-sidebar-student-info strong {

  display: block;

  max-width: 185px;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;

  color: #ffffff;

  font-size: 13px;

  font-weight: 900;

}


.c360-sidebar-student-info span {

  display: block;

  margin-top: 3px;

  color: #b9add7;

  font-size: 10px;

  font-weight: 600;

}


.c360-student-arrow {

  color: #aaa0c2;

  font-size: 21px;

}


/* =========================================================
   NAVIGATION
   ========================================================= */

.c360-sidebar-nav {

  flex:
    1 1 auto;

  min-height: 0;

  padding:
    2px
    8px
    12px;

  overflow-y: auto;

  overflow-x: hidden;

  scrollbar-width: none;

  -ms-overflow-style: none;

}


.c360-sidebar-nav::-webkit-scrollbar {

  width: 0 !important;

  height: 0 !important;

  display: none !important;

}


.c360-nav-group {

  margin-bottom: 4px;

}


.c360-nav-heading {

  padding:
    17px
    9px
    8px;

  color: #9f94bd;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: .11em;

}


.c360-nav-link {

  position: relative;

  width: 100%;

  min-height: 46px;

  margin:
    3px
    0;

  padding:
    9px
    12px;

  display: flex;

  align-items: center;

  gap: 12px;

  border: 0;

  border-radius: 11px;

  background: transparent;

  color: #ddd8e8 !important;

  font-size: 14px;

  font-weight: 750;

  text-decoration: none !important;

  transition:
    background .2s ease,
    color .2s ease,
    transform .2s ease;

}


.c360-nav-link:hover {

  color: #ffffff !important;

  background:
    rgba(124,58,237,.16);

  transform:
    translateX(2px);

}


.c360-nav-link.active {

  color: #ffffff !important;

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    );

  font-weight: 900;

  box-shadow:
    0 7px 18px
    rgba(124,58,237,.28);

}


.c360-nav-link.active::before {

  content: "";

  position: absolute;

  left: 0;

  top: 8px;

  bottom: 8px;

  width: 4px;

  border-radius:
    0
    4px
    4px
    0;

  background: #c4b5fd;

}


.c360-nav-icon {

  width: 24px;

  height: 24px;

  min-width: 24px;

  display: flex;

  align-items: center;

  justify-content: center;

  color: #b8aecb;

}


.c360-nav-icon svg {

  width: 21px;

  height: 21px;

  fill: none;

  stroke: currentColor;

  stroke-width: 1.8;

  stroke-linecap: round;

  stroke-linejoin: round;

}


.c360-nav-link.active
.c360-nav-icon {

  color: #ffffff;

}


.c360-nav-text {

  min-width: 0;

  flex: 1;

  white-space: nowrap;

}


/* =========================================================
   SIDEBAR FOOTER
   ========================================================= */

.c360-sidebar-footer {

  flex:
    0 0 auto;

  padding:
    10px
    12px
    13px;

  border-top:
    1px solid rgba(255,255,255,.08);

  background:
    #120c2d;

}


.c360-journey-mini {

  padding: 12px;

  border-radius: 12px;

  background:
    linear-gradient(
      145deg,
      #1e143f,
      #21164a
    );

  border:
    1px solid #382963;

}


.c360-journey-label {

  color: #a69abd;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: .08em;

}


.c360-journey-progress {

  height: 7px;

  margin-top: 9px;

  border-radius: 8px;

  overflow: hidden;

  background: #30234f;

}


.c360-journey-fill {

  height: 100%;

  border-radius: 8px;

  background:
    linear-gradient(
      90deg,
      #7c3aed,
      #a855f7
    );

}


.c360-journey-score {

  margin-top: 6px;

  color: #c1b7d3;

  font-size: 10px;

  font-weight: 700;

}


/* =========================================================
   RIGHT PAGE
   ========================================================= */

.c360-right-page {

  position: absolute !important;

  top: 0;

  right: 0;

  bottom: 0;

  left: 285px;

  width: auto !important;

  height: 100vh !important;

  min-width: 0 !important;

  max-width: none !important;

  overflow-x: hidden;

  overflow-y: auto;

  background:
    linear-gradient(
      135deg,
      #f1f6fc 0%,
      #f7f4ff 50%,
      #f0f8f6 100%
    );

  scrollbar-width: none;

  -ms-overflow-style: none;

  transition:
    left .25s ease;

}


.c360-right-page::-webkit-scrollbar {

  width: 0 !important;

  height: 0 !important;

  display: none !important;

}


.campus360-interviews.sidebar-closed
.c360-right-page {

  left: 0;

}


/* =========================================================
   TOP NAVBAR
   WHITE ONLY
   ========================================================= */

.c360-topbar {

  position: sticky;

  top: 0;

  z-index: 5000;

  width: 100%;

  height: 78px;

  min-height: 78px;

  padding:
    0
    24px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  background: #ffffff;

  border-bottom:
    1px solid #dfe4ec;

  box-shadow:
    0 2px 10px
    rgba(20,39,60,.035);

}


/* =========================================================
   TOPBAR LEFT
   ========================================================= */

.c360-topbar-left {

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 13px;

}


.c360-menu-button {

  width: 42px;

  height: 42px;

  min-width: 42px;

  padding: 9px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  gap: 4px;

  border:
    1px solid #dce2ea;

  border-radius: 10px;

  background: #ffffff;

  cursor: pointer;

  transition: .2s ease;

}


.c360-menu-button:hover {

  background: #f1efff;

  border-color: #bcb5ff;

}


.c360-menu-button span {

  display: block;

  width: 19px;

  height: 2px;

  border-radius: 3px;

  background: #5362ee;

}


/* =========================================================
   TOP PAGE TITLE
   ========================================================= */

.c360-page-heading {

  min-width: 150px;

  display: flex;

  flex-direction: column;

}


.c360-page-heading span {

  color: #673cff;

  font-size: 9px;

  font-weight: 950;

  letter-spacing: 1.6px;

}


.c360-page-heading strong {

  margin-top: 5px;

  color: #172a33;

  font-size: 17px;

  font-weight: 900;

}


/* =========================================================
   TOP RIGHT
   ========================================================= */

.c360-topbar-right {

  margin-left: auto;

  display: flex;

  align-items: center;

  gap: 10px;

}


/* =========================================================
   REFRESH + NOTIFICATION ICON
   ========================================================= */

.c360-top-icon {

  position: relative;

  width: 41px;

  height: 41px;

  min-width: 41px;

  display: flex;

  align-items: center;

  justify-content: center;

  border:
    1px solid #dce2ea;

  border-radius: 10px;

  background: #ffffff;

  color: #536476;

  cursor: pointer;

  transition: .2s ease;

}


.c360-top-icon:hover {

  color: #673cff;

  border-color: #c9baff;

  background: #f8f5ff;

}


.c360-top-icon svg {

  width: 18px;

  height: 18px;

  fill: none;

  stroke: currentColor;

  stroke-width: 1.8;

  stroke-linecap: round;

  stroke-linejoin: round;

}


.c360-notification-button {

  border-color: #d9ddff;

}


.c360-notification-button svg {

  color: #4f46e5;

}


.c360-notification-dot {

  position: absolute;

  width: 7px;

  height: 7px;

  top: 6px;

  right: 6px;

  border-radius: 50%;

  background: #ff3b4f;

  border:
    1.5px solid #ffffff;

}


/* =========================================================
   TOP PROFILE
   ========================================================= */

.c360-top-profile {

  min-height: 45px;

  padding-left: 11px;

  display: flex;

  align-items: center;

  gap: 9px;

  border-left:
    1px solid #e0e4eb;

  color: inherit !important;

  text-decoration: none !important;

}


.c360-top-avatar {

  width: 39px;

  height: 39px;

  min-width: 39px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background:
    linear-gradient(
      135deg,
      #7659f4,
      #6654eb
    );

  color: #ffffff;

  font-size: 11px;

  font-weight: 900;

}


.c360-top-profile-info {

  min-width: 0;

  display: flex;

  flex-direction: column;

}


.c360-top-profile-info strong {

  display: block;

  max-width: 190px;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;

  color: #101828;

  font-size: 12px;

  font-weight: 900;

}


.c360-top-profile-info span {

  display: block;

  margin-top: 2px;

  color: #667085;

  font-size: 9px;

  font-weight: 600;

}


.c360-profile-chevron {

  color: #667085;

  font-size: 13px;

}


/* =========================================================
   PAGE CONTENT
   ========================================================= */

.c360-page-content {

  width: 100% !important;

  max-width: none !important;

  min-width: 0 !important;

  margin: 0 !important;

  padding:
    24px
    15px
    55px;

}


/* =========================================================
   INTERVIEWS TOP HERO CARD
   DARK PURPLE
   ========================================================= */

.interviews-header {

  position: relative;

  z-index: 1;

  width: 100%;

  min-height: 178px;

  margin: 0;

  padding:
    30px
    38px;

  display: flex;

  align-items: center;

  border-radius:
    18px;

  background:
    linear-gradient(
      135deg,
      #241044 0%,
      #32145b 52%,
      #45206d 100%
    ) !important;

  border:
    1px solid #5a357d !important;

  color: #ffffff !important;

  box-shadow:
    0 12px 30px
    rgba(50,20,80,.18);

}


.interviews-header-content {

  width: 100%;

}


.interviews-eyebrow {

  display: flex;

  align-items: center;

  gap: 9px;

  margin-bottom: 9px;

  color: #dccbff !important;

  font-size: 13px;

  font-weight: 850;

  letter-spacing: 1.5px;

}


.interviews-eyebrow-dot {

  width: 10px;

  height: 10px;

  flex: 0 0 10px;

  border-radius: 50%;

  background: #c4b5fd !important;

  box-shadow:
    0 0 0 6px
    rgba(196,181,253,.16);

}


.interviews-header h1 {

  margin: 0;

  color: #ffffff !important;

  font-size: 42px;

  line-height: 1.1;

  font-weight: 850;

  letter-spacing: -.8px;

}


.interviews-header p {

  max-width: 800px;

  margin:
    11px
    0
    0;

  color: #e5dcf0 !important;

  font-size: 17px;

  line-height: 1.55;

}


/* =========================================================
   MAIN
   ========================================================= */

.interviews-main-content {

  width: 100%;

  padding-top: 25px;

}


/* =========================================================
   KPI GRID
   ========================================================= */

.interviews-kpi-grid {

  width: 100%;

  display: grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap: 17px;

  margin-bottom: 31px;

}


.interviews-kpi-card {

  position: relative;

  min-height: 126px;

  padding: 19px;

  display: flex;

  align-items: flex-start;

  gap: 13px;

  background: #ffffff;

  border:
    1px solid #d8e2ed;

  border-radius: 15px;

  box-shadow:
    0 5px 17px
    rgba(25,43,60,.045);

  overflow: hidden;

}


.interviews-kpi-card::after {

  content: "";

  position: absolute;

  left: 0;

  right: 0;

  bottom: 0;

  height: 4px;

}


.interviews-kpi-purple::after {
  background: #7040ff;
}

.interviews-kpi-blue::after {
  background: #159bb1;
}

.interviews-kpi-green::after {
  background: #16a34a;
}

.interviews-kpi-orange::after {
  background: #dc8b00;
}


.interviews-kpi-icon {

  width: 40px;

  height: 40px;

  flex: 0 0 40px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 10px;

  font-size: 18px;

  font-weight: 800;

}


.interviews-kpi-purple
.interviews-kpi-icon {

  color: #7040ff;

  background: #eee7ff;

}


.interviews-kpi-blue
.interviews-kpi-icon {

  color: #0d91a7;

  background: #d9f7fb;

}


.interviews-kpi-green
.interviews-kpi-icon {

  color: #16a34a;

  background: #dcfce7;

}


.interviews-kpi-orange
.interviews-kpi-icon {

  color: #d17a00;

  background: #fff0c9;

}


.interviews-kpi-text {

  min-width: 0;

}


.interviews-kpi-text > span {

  display: block;

  color: #637188;

  font-size: 11px;

  font-weight: 850;

  letter-spacing: 1px;

}


.interviews-kpi-text > strong {

  display: block;

  margin-top: 7px;

  color: #0d203a;

  font-size: 31px;

  line-height: 1;

  font-weight: 850;

}


.interviews-kpi-text > p {

  margin:
    7px
    0
    0;

  color: #8290a4;

  font-size: 12px;

}


/* =========================================================
   SECTIONS
   ========================================================= */

.interviews-section {

  width: 100%;

  margin-bottom: 36px;

}


.interviews-section-heading {

  margin-bottom: 14px;

  display: flex;

  align-items: flex-end;

  justify-content: space-between;

  gap: 15px;

}


.interviews-section-title {

  display: flex;

  align-items: center;

  gap: 9px;

}


.interviews-section-marker {

  width: 5px;

  height: 27px;

  border-radius: 10px;

}


.upcoming-marker {

  background: #0e8f87;

}


.history-marker {

  background: #16a34a;

}


.interviews-section-title h2 {

  margin: 0;

  color: #0a1d38;

  font-size: 24px;

  font-weight: 800;

}


.interviews-section-heading p {

  margin:
    6px
    0
    0
    14px;

  color: #687a91;

  font-size: 14px;

}


.interviews-updated {

  color: #8a97aa;

  font-size: 11px;

}


/* =========================================================
   UPCOMING INTERVIEWS
   ========================================================= */

.interviews-list {

  width: 100%;

  display: flex;

  flex-direction: column;

  gap: 13px;

}


.interview-card {

  position: relative;

  width: 100%;

  background: #ffffff;

  border:
    1px solid #d8e2ed;

  border-radius: 15px;

  overflow: hidden;

  box-shadow:
    0 5px 17px
    rgba(25,43,60,.045);

  transition:
    transform .18s ease,
    box-shadow .18s ease;

}


.interview-card:hover {

  transform:
    translateY(-2px);

  box-shadow:
    0 10px 25px
    rgba(25,43,60,.075);

}


.interview-card-status {

  width: 100%;

  height: 5px;

}


.status-line-scheduled {
  background: #7040ff;
}

.status-line-progress {
  background: #159bb1;
}

.status-line-completed {
  background: #16a34a;
}

.status-line-default {
  background: #94a3b8;
}


/* =========================================================
   INTERVIEW INNER
   ========================================================= */

.interview-card-inner {

  min-height: 148px;

  padding:
    18px
    19px;

  display: grid;

  grid-template-columns:
    minmax(280px,1.15fr)
    minmax(330px,1.35fr)
    155px;

  align-items: center;

  gap: 20px;

}


/* =========================================================
   MAIN INTERVIEW INFO
   ========================================================= */

.interview-main-info {

  min-width: 0;

  display: flex;

  align-items: flex-start;

  gap: 13px;

}


.interview-main-icon {

  width: 48px;

  height: 48px;

  min-width: 48px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  font-size: 20px;

  font-weight: 800;

}


.icon-scheduled {

  color: #7040ff;

  background: #eee7ff;

}


.icon-progress {

  color: #087f93;

  background: #d8f7fb;

}


.icon-completed {

  color: #15803d;

  background: #dcfce7;

}


.interview-main-text {

  min-width: 0;

}


.interview-title-row {

  display: flex;

  align-items: center;

  flex-wrap: wrap;

  gap: 7px;

}


.interview-title-row h3 {

  margin: 0;

  color: #0a1d38;

  font-size: 20px;

  line-height: 1.2;

  font-weight: 800;

}


.interview-type {

  margin-top: 5px;

  color: #53677f;

  font-size: 14px;

  font-weight: 600;

}


/* =========================================================
   STATUS
   ========================================================= */

.interview-status-pill {

  display: inline-flex;

  align-items: center;

  gap: 5px;

  padding:
    5px
    9px;

  border-radius: 20px;

  font-size: 10px;

  font-weight: 850;

}


.status-scheduled {

  color: #7040ff;

  background: #eee7ff;

}


.status-progress {

  color: #087f93;

  background: #d8f7fb;

}


.status-completed {

  color: #15803d;

  background: #dcfce7;

}


.status-default {

  color: #64748b;

  background: #eef2f7;

}


.interview-status-dot {

  width: 5px;

  height: 5px;

  border-radius: 50%;

  background: currentColor;

}


/* =========================================================
   ATTENDANCE
   ========================================================= */

.interview-attendance {

  width: fit-content;

  margin-top: 9px;

  padding:
    6px
    9px;

  display: flex;

  align-items: center;

  gap: 4px;

  border-radius: 7px;

  font-size: 11px;

}


.interview-attendance strong {

  font-weight: 850;

}


.attendance-present {

  color: #15803d;

  background: #ecfdf3;

}


.attendance-absent {

  color: #dc2626;

  background: #fef2f2;

}


.attendance-pending {

  color: #b45309;

  background: #fff7ed;

}


/* =========================================================
   DETAILS
   ========================================================= */

.interview-detail-grid {

  min-width: 0;

  display: grid;

  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap: 8px;

}


.interview-detail-item {

  min-width: 0;

  min-height: 62px;

  padding: 9px;

  display: flex;

  align-items: center;

  gap: 8px;

  border:
    1px solid #edf1f6;

  border-radius: 10px;

  background: #f8fafc;

}


.interview-detail-icon {

  width: 29px;

  height: 29px;

  min-width: 29px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 7px;

  background: #ffffff;

  font-size: 13px;

}


.interview-detail-item div {

  min-width: 0;

}


.interview-detail-item small {

  display: block;

  margin-bottom: 3px;

  color: #8997aa;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: .9px;

}


.interview-detail-item strong {

  display: block;

  color: #344964;

  font-size: 11px;

  font-weight: 780;

  white-space: nowrap;

  overflow: hidden;

  text-overflow: ellipsis;

}


/* =========================================================
   ACTIONS
   ========================================================= */

.interview-actions {

  display: flex;

  flex-direction: column;

  gap: 8px;

}


.interview-view-button,
.interview-start-button,
.interview-progress-button,
.qr-refresh-button {

  width: 100%;

  min-height: 39px;

  padding:
    8px
    11px;

  border-radius: 8px;

  font-family: inherit;

  font-size: 11px;

  font-weight: 800;

  cursor: pointer;

}


.interview-view-button {

  color: #334964;

  background: #ffffff;

  border:
    1px solid #cbd7e5;

}


.interview-view-button:hover {

  background: #f6f8fb;

}


.interview-start-button {

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #7040ff,
      #875eff
    );

  border:
    1px solid #7040ff;

  box-shadow:
    0 4px 10px
    rgba(112,64,255,.18);

}


.interview-start-button:hover {

  filter: brightness(.96);

}


.interview-progress-button {

  color: #087f93;

  background: #e9f9fb;

  border:
    1px solid #c8edf2;

  cursor: default;

}


/* =========================================================
   HISTORY
   ========================================================= */

.interviews-history-list {

  display: flex;

  flex-direction: column;

  gap: 11px;

}


.interview-history-card {

  min-height: 103px;

  padding:
    16px
    19px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 20px;

  background: #ffffff;

  border:
    1px solid #d8e2ed;

  border-left:
    4px solid #16a34a;

  border-radius: 14px;

  box-shadow:
    0 4px 15px rgba(25,43,60,.04);

}


.interview-history-card:nth-child(4n + 1) {

  border-left-color: #7040ff;

}


.interview-history-card:nth-child(4n + 2) {

  border-left-color: #159bb1;

}


.interview-history-card:nth-child(4n + 3) {

  border-left-color: #e08a00;

}


.interview-history-card:nth-child(4n + 4) {

  border-left-color: #16a34a;

}


.history-left {

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 12px;

}


.history-icon {

  width: 44px;

  height: 44px;

  min-width: 44px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  background: #dcfce7;

  color: #15803d;

  font-size: 18px;

  font-weight: 800;

}


.history-information {

  min-width: 0;

}


.history-title-row {

  display: flex;

  align-items: center;

  gap: 7px;

  flex-wrap: wrap;

}


.history-title-row h3 {

  margin: 0;

  color: #0a1d38;

  font-size: 18px;

  font-weight: 800;

}


.history-completed-pill {

  padding:
    5px
    9px;

  border-radius: 20px;

  color: #15803d;

  background: #dcfce7;

  font-size: 10px;

  font-weight: 850;

}


.history-type {

  margin-top: 4px;

  color: #53677f;

  font-size: 13px;

}


.history-meta {

  margin-top: 6px;

  display: flex;

  gap: 13px;

  flex-wrap: wrap;

  color: #8794a7;

  font-size: 11px;

}


.history-right {

  flex-shrink: 0;

  display: flex;

  align-items: center;

  gap: 18px;

}


/* =========================================================
   HISTORY SCORE
   ========================================================= */

.history-score {

  min-width: 82px;

  padding:
    8px
    10px;

  display: flex;

  flex-direction: column;

  align-items: center;

  border-radius: 10px;

  background: #f1edff;

  border:
    1px solid #ddd2ff;

}


.history-score strong {

  color: #7040ff;

  font-size: 27px;

  line-height: 1;

  font-weight: 900;

}


.history-score span {

  margin-top: 5px;

  color: #725bb4;

  font-size: 9px;

  font-weight: 750;

  white-space: nowrap;

}


.history-no-score {

  padding:
    10px
    12px;

  color: #94a3b8;

  background: #f8fafc;

  border-radius: 8px;

  font-size: 11px;

}


/* =========================================================
   HISTORY BUTTON
   ========================================================= */

.history-right
.interview-view-button {

  width: auto;

  min-width: 132px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      #7040ff,
      #875eff
    );

  border:
    1px solid #7040ff;

  box-shadow:
    0 5px 12px
    rgba(112,64,255,.18);

}


.interview-history-card:nth-child(4n + 2)
.history-right
.interview-view-button {

  background:
    linear-gradient(
      135deg,
      #0794aa,
      #18b1c3
    );

  border-color: #0794aa;

}


.interview-history-card:nth-child(4n + 3)
.history-right
.interview-view-button {

  background:
    linear-gradient(
      135deg,
      #dc8500,
      #efaa24
    );

  border-color: #dc8500;

}


.interview-history-card:nth-child(4n + 4)
.history-right
.interview-view-button {

  background:
    linear-gradient(
      135deg,
      #159447,
      #26b45d
    );

  border-color: #159447;

}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.interviews-empty {

  min-height: 190px;

  padding: 30px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  text-align: center;

  border:
    1px solid #d8e2ed;

  border-radius: 15px;

  background: #ffffff;

}


.interviews-empty-icon {

  width: 48px;

  height: 48px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  color: #6638d0;

  background: #eee7ff;

  font-size: 22px;

}


.interviews-empty h3 {

  margin:
    10px
    0
    4px;

  color: #0a1d38;

  font-size: 18px;

}


.interviews-empty p {

  margin: 0;

  color: #687a91;

  font-size: 13px;

}


/* =========================================================
   LOADING
   ========================================================= */

.interviews-loading {

  min-height: 300px;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 10px;

  color: #53677f;

  font-size: 14px;

  font-weight: 700;

}


.interviews-spinner {

  width: 21px;

  height: 21px;

  border:
    3px solid #ded6f7;

  border-top-color: #7040ff;

  border-radius: 50%;

  animation:
    c360InterviewSpin
    .8s linear infinite;

}


@keyframes c360InterviewSpin {

  to {
    transform:
      rotate(360deg);
  }

}


/* =========================================================
   MODALS
   ========================================================= */

.interview-modal-backdrop {

  position: fixed;

  inset: 0;

  z-index: 50000;

  padding: 20px;

  display: flex;

  align-items: center;

  justify-content: center;

  background:
    rgba(12,25,43,.60);

}


.interview-modal {

  position: relative;

  width:
    min(680px,100%);

  max-height: 90vh;

  overflow-y: auto;

  border-radius: 16px;

  background: #ffffff;

  box-shadow:
    0 25px 70px rgba(15,23,42,.25);

}


.interview-modal-close {

  position: absolute;

  top: 14px;

  right: 15px;

  z-index: 5;

  width: 34px;

  height: 34px;

  border: 0;

  border-radius: 8px;

  background: #f1f4f8;

  color: #536178;

  font-size: 21px;

  cursor: pointer;

}


.interview-modal-header {

  padding:
    26px
    26px
    18px;

}


.interview-modal-eyebrow {

  margin-bottom: 7px;

  color: #7040ff;

  font-size: 11px;

  font-weight: 900;

  letter-spacing: 1.3px;

}


.interview-modal-header h2 {

  margin: 0;

  color: #0a1d38;

  font-size: 25px;

  font-weight: 820;

}


.interview-modal-header p {

  margin:
    6px
    0
    0;

  color: #718096;

  font-size: 13px;

}


.interview-modal-details {

  padding:
    0
    26px
    20px;

  display: grid;

  grid-template-columns:
    repeat(2,1fr);

  gap: 11px;

}


.modal-detail-item {

  position: relative;

  min-height: 62px;

  padding:
    13px
    14px;

  border:
    1px solid #e8edf3;

  border-radius: 10px;

  background: #f8fafc;

  overflow: hidden;

}


.modal-detail-item::before {

  content: "";

  position: absolute;

  left: 0;

  top: 0;

  bottom: 0;

  width: 4px;

  background: #7040ff;

}


.modal-detail-item:nth-child(1) {
  background: #f6f2ff;
  border-color: #ded4ff;
}

.modal-detail-item:nth-child(2) {
  background: #edfafd;
  border-color: #c9edf2;
}

.modal-detail-item:nth-child(3) {
  background: #eef6ff;
  border-color: #d1e3fa;
}

.modal-detail-item:nth-child(4) {
  background: #fff7e9;
  border-color: #f4dfb7;
}

.modal-detail-item:nth-child(5) {
  background: #eefaf1;
  border-color: #cee9d5;
}

.modal-detail-item:nth-child(6) {
  background: #fff0f7;
  border-color: #f4cce0;
}


.modal-detail-item:nth-child(1)::before {
  background: #7040ff;
}

.modal-detail-item:nth-child(2)::before {
  background: #0b91a7;
}

.modal-detail-item:nth-child(3)::before {
  background: #2878c7;
}

.modal-detail-item:nth-child(4)::before {
  background: #df8a00;
}

.modal-detail-item:nth-child(5)::before {
  background: #16a34a;
}

.modal-detail-item:nth-child(6)::before {
  background: #df2d79;
}


.modal-detail-item span {

  display: block;

  margin-bottom: 5px;

  color: #7e8da1;

  font-size: 9px;

  font-weight: 900;

  letter-spacing: .8px;

}


.modal-detail-item strong {

  color: #344964;

  font-size: 13px;

  font-weight: 800;

}


.interview-modal-footer {

  padding:
    13px
    26px
    20px;

  display: flex;

  justify-content: flex-end;

  gap: 9px;

  border-top:
    1px solid #edf1f6;

}


/* =========================================================
   QR MODAL
   ========================================================= */

.interview-qr-modal {

  position: relative;

  width:
    min(600px,100%);

  height:
    min(750px,92vh);

  display: flex;

  flex-direction: column;

  overflow: hidden;

  border-radius: 16px;

  background: #ffffff;

}


.qr-header {

  padding:
    22px
    50px
    9px;

  text-align: center;

}


.qr-icon {

  width: 45px;

  height: 45px;

  margin:
    0
    auto
    8px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  color: #7040ff;

  background: #eee7ff;

  font-size: 20px;

}


.qr-header h2 {

  margin: 0;

  color: #0a1d38;

  font-size: 22px;

  font-weight: 820;

}


.qr-header p {

  margin:
    5px
    0
    0;

  color: #718096;

  font-size: 13px;

}


.qr-frame-wrapper {

  flex: 1;

  min-height: 0;

  padding:
    5px
    14px;

}


.qr-frame {

  width: 100%;

  height: 100%;

  border: 0;

  border-radius: 9px;

}


.qr-information {

  margin:
    7px
    14px;

  padding: 12px;

  border:
    1px solid #bfe9ce;

  border-radius: 9px;

  background: #effbf4;

}


.qr-information strong {

  display: block;

  color: #166534;

  font-size: 12px;

}


.qr-information span {

  display: block;

  margin-top: 3px;

  color: #4d7c65;

  font-size: 11px;

}


.qr-refresh-button {

  width: auto;

  color: #7040ff;

  background: #f1edff;

  border:
    1px solid #ddd2ff;

}


/* =========================================================
   PERFORMANCE MODAL
   ========================================================= */

.performance-score-grid {

  padding:
    0
    26px;

  display: grid;

  grid-template-columns:
    repeat(4,1fr);

  gap: 10px;

}


.performance-score-item {

  padding:
    14px
    8px;

  text-align: center;

  border:
    1px solid #e7edf4;

  border-radius: 10px;

  background: #f8fafc;

}


.performance-score-item span {

  display: block;

  color: #718096;

  font-size: 10px;

  font-weight: 780;

}


.performance-score-item strong {

  display: block;

  margin-top: 6px;

  color: #172033;

  font-size: 23px;

  font-weight: 900;

}


.performance-score-item:nth-child(1) {

  background: #eee7ff;

  border-color: #d8caff;

}


.performance-score-item:nth-child(1) strong {

  color: #7040ff;

}


.performance-score-item:nth-child(2) {

  background: #e8f9fc;

  border-color: #c7edf2;

}


.performance-score-item:nth-child(2) strong {

  color: #0b8195;

}


.performance-score-item:nth-child(3) {

  background: #fff4df;

  border-color: #f1dcae;

}


.performance-score-item:nth-child(3) strong {

  color: #c56f00;

}


.performance-score-item.overall {

  background:
    linear-gradient(
      135deg,
      #f0eaff,
      #e7ddff
    );

  border-color: #cdbaff;

}


.performance-score-item.overall strong {

  color: #7040ff;

  font-size: 25px;

}


.feedback-section {

  padding:
    18px
    26px
    8px;

}


.feedback-box {

  position: relative;

  margin-bottom: 11px;

  padding:
    13px
    14px
    13px
    16px;

  border-radius: 10px;

  background: #f8fafc;

  border:
    1px solid #e7edf4;

  overflow: hidden;

}


.feedback-box::before {

  content: "";

  position: absolute;

  left: 0;

  top: 0;

  bottom: 0;

  width: 4px;

  background: #7040ff;

}


.feedback-box:nth-child(1) {

  background: #f5f1ff;

  border-color: #ded4ff;

}


.feedback-box:nth-child(2) {

  background: #eefafd;

  border-color: #c9edf2;

}


.feedback-box:nth-child(3) {

  background: #fff7e9;

  border-color: #f2dfb8;

}


.feedback-box h4 {

  margin:
    0
    0
    6px;

  color: #344964;

  font-size: 13px;

  font-weight: 800;

}


.feedback-box p {

  margin: 0;

  color: #657189;

  font-size: 12px;

  line-height: 1.55;

}


.performance-empty {

  padding:
    40px
    25px;

  text-align: center;

}


.performance-empty h3 {

  color: #344964;

  font-size: 18px;

}


.performance-empty p {

  color: #718096;

  font-size: 13px;

}


/* =========================================================
   MOBILE OVERLAY
   ========================================================= */

.c360-sidebar-overlay {

  display: none;

}


/* =========================================================
   LARGE DESKTOP
   ========================================================= */

@media (min-width: 1600px) {

  .c360-page-content {

    padding-left:
      15px;

    padding-right:
      15px;

  }

}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 1200px) {

  .interviews-kpi-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


  .interview-card-inner {

    grid-template-columns:
      minmax(250px,1fr)
      minmax(280px,1fr);

  }


  .interview-actions {

    grid-column:
      1 / -1;

    flex-direction:
      row;

    justify-content:
      flex-end;

  }


  .interview-actions button {

    width:
      auto;

  }

}


/* =========================================================
   TABLET / MOBILE
   ========================================================= */

@media (max-width: 900px) {

  .c360-left-sidebar {

    position: fixed !important;

    top: 0;

    left: 0;

    bottom: 0;

    width: 285px !important;

    min-width: 285px !important;

    max-width: 285px !important;

    transform:
      translateX(-105%);

    box-shadow:
      8px 0 25px
      rgba(25,43,60,.13);

  }


  .campus360-interviews.sidebar-open
  .c360-left-sidebar {

    transform:
      translateX(0);

  }


  .campus360-interviews.sidebar-closed
  .c360-left-sidebar {

    transform:
      translateX(-105%);

  }


  .c360-sidebar-overlay {

    position: fixed;

    inset: 0;

    z-index: 90;

    display: block;

    background:
      rgba(15,28,45,.35);

  }


  .campus360-interviews.sidebar-closed
  .c360-sidebar-overlay {

    display: none;

  }


  .c360-right-page {

    left: 0 !important;

    width: 100vw !important;

  }


  /* Keep dark-purple Interviews card
     separated from the white navbar on mobile. */

  .c360-page-content {

    padding-top:
      18px;

  }

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 650px) {

  .c360-topbar {

    height: 68px;

    min-height: 68px;

    padding:
      0
      11px;

  }


  .c360-page-heading {

    display: none;

  }


  .c360-top-profile-info,
  .c360-profile-chevron {

    display: none;

  }


  .c360-top-profile {

    padding-left: 3px;

  }


  .c360-topbar-right {

    gap: 5px;

  }


  .c360-top-icon {

    width: 37px;

    height: 37px;

    min-width: 37px;

  }


  .c360-top-avatar {

    width: 37px;

    height: 37px;

    min-width: 37px;

  }


  .c360-page-content {

    padding:
      14px
      10px
      45px;

  }


  .interviews-header {

    min-height:
      160px;

    padding:
      25px
      22px;

    border-radius:
      15px;

  }


  .interviews-header h1 {

