  }


  .interviews-header p {

    font-size:
      14px;

  }


  .interviews-kpi-grid {

    grid-template-columns:
      1fr;

  }


  .interview-card-inner {

    grid-template-columns:
      1fr;

  }


  .interview-detail-grid {

    grid-template-columns:
      1fr;

  }


  .interview-actions {

    grid-column:
      auto;

    flex-direction:
      column;

  }


  .interview-actions button {

    width:
      100%;

  }


  .interview-history-card {

    align-items:
      flex-start;

    flex-direction:
      column;

  }


  .history-right {

    width:
      100%;

    justify-content:
      space-between;

  }


  .history-right
