    min-width:
      120px;

  }


  .interview-modal-details {

    grid-template-columns:
      1fr;

  }


  .performance-score-grid {

    grid-template-columns:
      repeat(2,1fr);

  }

}


/* =========================================================
   VERY SMALL MOBILE
   ========================================================= */

@media (max-width: 430px) {

  .c360-topbar {

    height: 62px;

    min-height: 62px;

  }


  .c360-menu-button {

    width: 37px;

    height: 37px;

    min-width: 37px;

  }


  .c360-menu-button span {

    width: 17px;

  }


  .interviews-header h1 {

    font-size: 29px;

  }


  .interview-title-row h3 {

    font-size: 18px;

  }


  .history-right {

    flex-wrap: wrap;

  }


  .history-right
  .interview-view-button {

    width:
      100%;

  }

}


/* =========================================================
   FINAL FULL-VIEW SAFETY
   ========================================================= */

.campus360-interviews {

  margin-top: 0 !important;

  margin-bottom: 0 !important;

}


.campus360-interviews .c360-right-page {

  margin-left: 0 !important;

  margin-right: 0 !important;

}


.campus360-interviews .c360-page-content {

  width: 100% !important;

  max-width: none !important;

}


/* Never display an unintended external navigation bar
   above the Campus360 application. */

body:has(.campus360-interviews) > header,
body:has(.campus360-interviews) > nav {

