sp_widget.script:
(function() {


    /* =====================================================
       INITIAL DATA
       ===================================================== */

    data.stats = {

        total: 0,

        upcoming: 0,

        completed: 0,

        avgScore: null

    };


    data.interviews = [];

    data.upcoming = [];

    data.history = [];


    /* =====================================================
       GET STUDENT
       ===================================================== */

    var studentId =
        $sp.getParameter('student') ||
        'STU_TEST_001';


    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    studentGR.addQuery(
        'student_id',
        studentId
    );


    studentGR.query();


    if (!studentGR.next()) {

        data.error =
            'Student record not found: ' +
            studentId;

        return;

    }


    var studentSysId =
        studentGR.getUniqueValue();


    /* =====================================================
       LOAD MOCK INTERVIEWS
       ===================================================== */

    var interviewGR =
        new GlideRecord(
            'x_snc_campus360_mock_interview'
        );


    interviewGR.addQuery(
        'student',
        studentSysId
    );


    interviewGR.orderByDesc(
        'interview_date'
    );


    interviewGR.query();


    var totalScore = 0;

    var scoreCount = 0;


    /* =====================================================
       PROCESS INTERVIEWS
       ===================================================== */

    while (
        interviewGR.next()
    ) {


        var interview = {

            sys_id:
                interviewGR.getUniqueValue(),


            interview_id:
                interviewGR.getDisplayValue(
                    'interview_id'
                ),


            interview_status:
                interviewGR.getDisplayValue(
                    'interview_status'
                ),


            interview_type:
                interviewGR.getDisplayValue(
                    'interview_type'
                ),


            interview_date:
                interviewGR.getDisplayValue(
                    'interview_date'
                ),


            start_time:
                interviewGR.getDisplayValue(
                    'start_time'
                ),


            end_time:
                interviewGR.getDisplayValue(
                    'end_time'
                ),


            trainer:
                interviewGR.getDisplayValue(
                    'trainer'
                ),


            attendance_status:
                interviewGR.getDisplayValue(
                    'attendance_status'
                ),


            qr_status:
                interviewGR.getDisplayValue(
                    'qr_status'
                ),


            qr_code:
                interviewGR.getValue(
                    'qr_code'
                ),


            qr_url:
                interviewGR.getValue(
                    'qr_url'
                ),


            feedback: null

        };


        /* =================================================
           FEEDBACK
           ================================================= */

        var feedbackGR =
            new GlideRecord(
                'x_snc_campus360_interview_feedback'
            );


        feedbackGR.addQuery(
            'interview',
            interviewGR.getUniqueValue()
        );


        feedbackGR.orderByDesc(
            'sys_created_on'
        );


        feedbackGR.setLimit(1);


        feedbackGR.query();


        if (
            feedbackGR.next()
        ) {


            interview.feedback = {

                feedback_id:
                    feedbackGR.getDisplayValue(
                        'feedback_id'
                    ),


                technical_score:
                    getInteger(
                        feedbackGR,
                        'technical_score'
                    ),


                communication_score:
                    getInteger(
                        feedbackGR,
                        'communication_score'
                    ),


                problem_solving_score:
                    getInteger(
                        feedbackGR,
                        'problem_solving_score'
                    ),


                overall_score:
                    getInteger(
                        feedbackGR,
                        'overall_score'
                    ),


                strengths:
                    feedbackGR.getDisplayValue(
                        'strengths'
                    ),


                improvement_areas:
                    feedbackGR.getDisplayValue(
                        'improvement_areas'
                    ),


                recommendation:
                    feedbackGR.getDisplayValue(
                        'recommendation'
                    ),


                feedback_date:
                    feedbackGR.getDisplayValue(
                        'feedback_date'
                    ),


                trainer:
                    feedbackGR.getDisplayValue(
                        'trainer'
                    )

            };


            if (
                interview.feedback.overall_score !== null
            ) {

                totalScore +=
                    interview.feedback.overall_score;

                scoreCount++;

            }

        }


        /* =================================================
           ALL INTERVIEWS
           ================================================= */

        data.interviews.push(
            interview
        );


        /* =================================================
           UPCOMING / HISTORY
           ================================================= */

        var status =
            String(
                interview.interview_status ||
                ''
            ).toLowerCase();


        if (
            status === 'completed'
        ) {

            data.history.push(
                interview
            );

            data.stats.completed++;

        }
        else {

            data.upcoming.push(
                interview
            );

            data.stats.upcoming++;

        }

    }


    /* =====================================================
       STATS
       ===================================================== */

    data.stats.total =
        data.interviews.length;


    if (
        scoreCount > 0
    ) {

        data.stats.avgScore =
            Math.round(
                (
                    totalScore /
                    scoreCount
                ) * 10
            ) / 10;

    }


    /* =====================================================
       INTEGER HELPER
       ===================================================== */

    function getInteger(
        gr,
        fieldName
    ) {

        if (
            !gr.isValidField(
                fieldName
            )
        ) {

            return null;

        }


        var value =
            gr.getValue(
                fieldName
            );


        if (
            value === null ||
            value === undefined ||
            value === ''
        ) {

            return null;

        }


        var number =
            parseInt(
                value,
                10
            );


        if (
            isNaN(number)
        ) {

            return null;

        }


        return number;

    }


})();

data.aiWidget = $sp.getWidget('campus360_ai_assistant');
